package com.example.appointment.staff;
import com.example.appointment.common.BaseEntity; import java.time.*; import javax.persistence.*;
@Entity @Table(name="staff_availability") public class Availability extends BaseEntity { @ManyToOne(optional=false) private StaffProfile staff; @Column(name="available_date",nullable=false) private LocalDate date; @Column(nullable=false) private LocalTime startTime; @Column(nullable=false) private LocalTime endTime; protected Availability(){} public Availability(StaffProfile s,LocalDate d,LocalTime a,LocalTime b){if(!a.isBefore(b))throw new IllegalArgumentException("startTime must be before endTime");staff=s;date=d;startTime=a;endTime=b;} public StaffProfile getStaff(){return staff;} public LocalDate getDate(){return date;} public LocalTime getStartTime(){return startTime;} public LocalTime getEndTime(){return endTime;} public void update(LocalDate d,LocalTime a,LocalTime b){if(!a.isBefore(b))throw new IllegalArgumentException("startTime must be before endTime");date=d;startTime=a;endTime=b;} }
